        Path jspTagFile = jspRoot.resolve(jspTag);
        String relativeFilePath = jspRoot.relativize(jspTagFile).toString();
        JtpConverter converter = createConverter(relativeFilePath, readFile(jspTagFile), parserSetup, Collections.emptySet());
        String jte = converter.convert();

        System.out.println(jte);
        checkDependencies(jte);

        String jteTemplate = suggestJteFile(jspTag.replace('\\', '/'));
        Path jteTemplateFile = jteRoot.resolve(jteTemplate);
        IoUtils.writeFile(jteTemplateFile, jte);
        replaceUsages(jspTagFile, jteTemplateFile);
    }

    public JspMigrationPlan planTags(Collection<String> jspTags, Consumer<Converter> parserSetup) {
        if (jspTags == null || jspTags.isEmpty()) {
            throw new IllegalArgumentException("At least one JSP tag is required.");
        }

        Map<Path, String> selectedRelativePaths = new TreeMap<>(PATH_COMPARATOR);
        for (String jspTag : jspTags) {
            Path relativePath = validateSelectedPath(jspTag);
            if (selectedRelativePaths.put(relativePath, toPortablePath(relativePath)) != null) {
                throw new IllegalArgumentException("Duplicate JSP tag path: " + relativePath);
            }
        }

        Map<String, Path> invocationPaths = new HashMap<>();
        for (Path relativePath : selectedRelativePaths.keySet()) {
            String invocationName = extractTagPrefix(jspRoot.resolve(relativePath)).substring(1);
            Path previous = invocationPaths.put(invocationName, relativePath);
            if (previous != null) {
                throw new IllegalArgumentException("Ambiguous selected invocation name <" + invocationName + "> for " + previous + " and " + relativePath);
            }
        }

        Map<Path, Path> destinations = validateDestinations(selectedRelativePaths);
        Map<Path, String> initialContents = scanJspFiles();
        Map<Path, byte[]> snapshots = new TreeMap<>(PATH_COMPARATOR);
        initialContents.forEach((path, content) -> snapshots.put(path, content.getBytes(StandardCharsets.UTF_8)));

        Map<Path, JtpConverter> configuredConverters = new TreeMap<>(PATH_COMPARATOR);
        Map<Path, Set<Path>> dependencies = new TreeMap<>(PATH_COMPARATOR);
        Set<String> selectedInvocationNames = invocationPaths.keySet();
        for (Map.Entry<Path, String> selected : selectedRelativePaths.entrySet()) {
            Path absolutePath = jspRoot.resolve(selected.getKey()).normalize();
            String content = initialContents.get(absolutePath);
            if (content == null) {
                content = readFile(absolutePath);
                initialContents.put(absolutePath, content);
                snapshots.put(absolutePath, content.getBytes(StandardCharsets.UTF_8));
            }

            JtpConverter converter = createConverter(selected.getValue(), content, parserSetup, selectedInvocationNames);
            converter.analyze();
            validateApprovedIncludes(converter, snapshots, initialContents);

            Set<Path> tagDependencies = new TreeSet<>(PATH_COMPARATOR);
            for (String invocation : converter.getEncounteredCustomTags()) {
                Path dependency = invocationPaths.get(invocation);
                if (dependency != null) {
                    tagDependencies.add(dependency);
                } else if (!converter.hasConverter(invocation)) {
                    throw unresolvedTag(invocation);
                }
            }
            dependencies.put(selected.getKey(), tagDependencies);
            configuredConverters.put(selected.getKey(), converter);
        }

        List<Path> conversionOrder = topologicalOrder(dependencies);
        Map<Path, String> virtualContents = new TreeMap<>(PATH_COMPARATOR);
        virtualContents.putAll(initialContents);
        Map<Path, String> generatedWrites = new TreeMap<>(PATH_COMPARATOR);

        for (Path relativePath : conversionOrder) {
            Path absolutePath = jspRoot.resolve(relativePath).normalize();
            String relativeFilePath = selectedRelativePaths.get(relativePath);
            JtpConverter converter = configuredConverters.get(relativePath).copyFor(
                    relativeFilePath,
                    normalizeInput(virtualContents.get(absolutePath))
            );
            String jte = converter.convert();
            checkDependencies(jte);
            Path destination = destinations.get(relativePath);
            generatedWrites.put(destination, jte);
            replaceVirtualUsages(virtualContents, absolutePath, destination);
        }

        Set<Path> deletes = new TreeSet<>(PATH_COMPARATOR);
        for (Path relativePath : selectedRelativePaths.keySet()) {
            deletes.add(jspRoot.resolve(relativePath).normalize());
        }

        Map<Path, String> writes = new TreeMap<>(PATH_COMPARATOR);
        writes.putAll(generatedWrites);
        for (Map.Entry<Path, String> entry : virtualContents.entrySet()) {
            if (!deletes.contains(entry.getKey()) && !Objects.equals(initialContents.get(entry.getKey()), entry.getValue())) {
                writes.put(entry.getKey(), entry.getValue());
            }
        }

        List<Path> absoluteOrder = new ArrayList<>(conversionOrder.size());
        for (Path relativePath : conversionOrder) {
            absoluteOrder.add(jspRoot.resolve(relativePath).normalize());
        }
        return new JspMigrationPlan(absoluteOrder, deletes, writes, snapshots, new TreeSet<>(generatedWrites.keySet()));
    }

    private Path validateSelectedPath(String jspTag) {
        if (jspTag == null || jspTag.isBlank()) {
            throw new IllegalArgumentException("JSP tag paths must not be null or blank.");
        }
        Path supplied = Paths.get(jspTag);
        if (supplied.isAbsolute()) {
            throw new IllegalArgumentException("JSP tag paths must be root-relative: " + jspTag);
        }
        Path relative = supplied.normalize();
        if (relative.toString().isEmpty() || relative.startsWith("..")) {
            throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + jspTag);
        }
        if (!toPortablePath(relative).endsWith(".tag")) {
            throw new IllegalArgumentException("JSP tag path must end with .tag: " + jspTag);
        }
        Path absolute = jspRoot.resolve(relative).normalize();
        if (!absolute.startsWith(jspRoot)) {
            throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + jspTag);
        }
        if (Files.isSymbolicLink(absolute)) {
            throw new IllegalArgumentException("Selected JSP tag must not be a symbolic link: " + absolute);
        }
        if (!Files.isRegularFile(absolute, LinkOption.NOFOLLOW_LINKS)) {
            throw new IllegalArgumentException("Selected JSP tag is missing or not a regular file: " + absolute);
        }
        return relative;
    }

    private Map<Path, Path> validateDestinations(Map<Path, String> selectedRelativePaths) {
        Map<Path, Path> result = new TreeMap<>(PATH_COMPARATOR);
        Set<Path> seen = new HashSet<>();
        for (Map.Entry<Path, String> selected : selectedRelativePaths.entrySet()) {
            String suggested = suggestJteFile(selected.getValue());
            if (suggested == null || suggested.isBlank()) {
                throw new IllegalArgumentException("Generated JTE destination must not be null or blank for " + selected.getKey());
            }
            Path suggestedPath = Paths.get(suggested);
            Path destination = jteRoot.resolve(suggestedPath).toAbsolutePath().normalize();
            if (suggestedPath.isAbsolute() || !destination.startsWith(jteRoot) || !isReallyWithin(destination, jteRoot)) {
                throw new IllegalArgumentException("Generated JTE destination is outside the JTE root: " + destination);
            }
            if (!seen.add(destination)) {
                throw new IllegalArgumentException("Generated JTE destinations collide at " + destination);
            }
            if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Generated JTE destination is already taken: " + destination);
            }
            result.put(selected.getKey(), destination);
        }
        return result;
    }

    private Map<Path, String> scanJspFiles() {
        Map<Path, String> result = new TreeMap<>(PATH_COMPARATOR);
        try (Stream<Path> stream = Files.walk(jspRoot)) {
            stream.filter(path -> Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS))
                    .map(path -> path.toAbsolutePath().normalize())
                    .filter(this::isUsageFile)
                    .sorted(PATH_COMPARATOR)
                    .forEach(path -> result.put(path, readFile(path)));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return result;
    }

    private boolean isUsageFile(Path path) {
        String fileName = path.toString();
        return fileName.endsWith(".jsp") || fileName.endsWith(".jsp.inc") || fileName.endsWith(".tag");
    }

    private void validateApprovedIncludes(JtpConverter converter, Map<Path, byte[]> snapshots, Map<Path, String> contents) {
        for (String include : converter.getInlinedIncludes()) {
            resolveApprovedInclude(include);
        }
        for (String include : converter.getEncounteredInlinedIncludes()) {
            Path includePath = resolveApprovedInclude(include);
            if (Files.isSymbolicLink(includePath) || !Files.isRegularFile(includePath, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Approved include is missing or not a regular file: " + includePath);
            }
            String content = contents.computeIfAbsent(includePath, this::readFile);
            snapshots.putIfAbsent(includePath, content.getBytes(StandardCharsets.UTF_8));
        }
    }

    private Path resolveApprovedInclude(String include) {
        if (include == null || include.isBlank()) {
            throw new IllegalArgumentException("Approved include paths must not be null or blank.");
        }
        Path resourceBase;
        try {
            URL url = getResourceBase();
            if (!"file".equalsIgnoreCase(url.getProtocol())) {
                throw new IllegalArgumentException("Approved includes require a file resource base: " + url);
            }
            resourceBase = Paths.get(url.toURI()).toAbsolutePath().normalize();
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid resource base", e);
        }
        String rootRelative = include.replace('\\', '/');
        while (rootRelative.startsWith("/")) {
            rootRelative = rootRelative.substring(1);
        }
        Path resolved = resourceBase.resolve(rootRelative).toAbsolutePath().normalize();
        if (!resolved.startsWith(jspRoot) || !isReallyWithin(resolved, jspRoot)) {
            throw new IllegalArgumentException("Approved include is outside the JSP root: " + resolved);
        }
        return resolved;
    }

    private boolean isReallyWithin(Path path, Path root) {
        try {
            return resolveWithExistingAncestors(path).startsWith(resolveWithExistingAncestors(root));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private Path resolveWithExistingAncestors(Path path) throws IOException {
        Path existing = path;
        List<Path> missing = new ArrayList<>();
        while (existing != null && !Files.exists(existing, LinkOption.NOFOLLOW_LINKS)) {
            missing.add(existing.getFileName());
            existing = existing.getParent();
        }
        if (existing == null) {
            return path.toAbsolutePath().normalize();
        }
        Path resolved = existing.toRealPath();
        for (int i = missing.size() - 1; i >= 0; i--) {
            resolved = resolved.resolve(missing.get(i));
        }
        return resolved.normalize();
    }

    private List<Path> topologicalOrder(Map<Path, Set<Path>> dependencies) {
        List<Path> result = new ArrayList<>(dependencies.size());
        Set<Path> converted = new HashSet<>();
        while (result.size() < dependencies.size()) {
            Path next = null;
            for (Map.Entry<Path, Set<Path>> entry : dependencies.entrySet()) {
                if (!converted.contains(entry.getKey()) && converted.containsAll(entry.getValue())) {
                    next = entry.getKey();
                    break;
                }
            }
            if (next == null) {
                throw new IllegalArgumentException("Cyclic JSP tag dependency: " + formatCycle(dependencies, converted));
            }
            converted.add(next);
            result.add(next);
        }
        return result;
    }

    private String formatCycle(Map<Path, Set<Path>> dependencies, Set<Path> converted) {
        Path start = dependencies.keySet().stream().filter(path -> !converted.contains(path)).findFirst().orElseThrow();
        List<Path> path = new ArrayList<>();
        Map<Path, Integer> indexes = new HashMap<>();
        Path current = start;
        while (!indexes.containsKey(current)) {
            indexes.put(current, path.size());
            path.add(current);
            current = dependencies.get(current).stream()
                    .filter(dependency -> !converted.contains(dependency))
                    .findFirst()
                    .orElseThrow();
        }
        List<Path> cycle = new ArrayList<>(path.subList(indexes.get(current), path.size()));
        cycle.add(current);
        List<String> portable = new ArrayList<>(cycle.size());
        for (Path element : cycle) {
            portable.add(toPortablePath(element));
        }
        return String.join(" -> ", portable);
    }

    private RuntimeException unresolvedTag(String invocation) {
        return new UnsupportedOperationException("The tag <" + invocation + "/> is used by this tag and not converted to jte yet. You should convert <" + invocation + "/> first. If this is a tag that should be always converted by hand, implement getNotConvertedTags() and add it there.");
    }

    private JtpConverter createConverter(String relativeFilePath, String content, Consumer<Converter> parserSetup, Set<String> selectedInvocationNames) {
        JtpConverter converter = new JtpConverter(
                relativeFilePath,
                normalizeInput(content),
                getResourceBase(),
                relativeFilePath.endsWith(".tag"),
                new ConverterOutput()
        );

        for (String selectedInvocationName : selectedInvocationNames) {
            converter.register(selectedInvocationName, new JspNoopConverter());
        }
        converter.register("c:if", new JspIfConverter());
        converter.register("c:forEach", new JspForEachConverter());
        converter.register("c:choose", new JspChooseConverter());
        converter.register("c:when", new JspWhenConverter());
        converter.register("c:otherwise", new JspOtherwiseConverter());
        converter.register("c:set", new JspSetConverter());
        converter.register("fmt:message", new JstlFmtMessageConverter());
        converter.register("fmt:param", new JstlFmtParamConverter());
        converter.register(jteTag, new JspJteConverter());

        String[] notConvertedTags = getNotConvertedTags();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                converter.register(notConvertedTag, new JspNoopConverter());
            }
        }
        if (parserSetup != null) {
            parserSetup.accept(converter);
        }
        return converter;
    }

    private byte[] normalizeInput(String content) {
        return content.replace("\r", "").getBytes(StandardCharsets.UTF_8);
    }

    private void replaceVirtualUsages(Map<Path, String> contents, Path jspTag, Path jteTagPath) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = toPortablePath(jteRoot.relativize(jteTagPath));
        for (Map.Entry<Path, String> entry : contents.entrySet()) {
            entry.setValue(replaceUsages(entry.getValue(), oldJspTagPrefix, oldJspTagClosing, newJteFile));
        }
    }

    @SuppressWarnings("unused")
    public void replaceUsages(String jspTag, String jteTag) {
        replaceUsages(jspRoot.resolve(jspTag), jteRoot.resolve(jteTag));
    }

    public void replaceUsages(Path jspTag, Path jteTag) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = toPortablePath(jteRoot.relativize(jteTag));

        IoUtils.deleteFile(jspTag);
        try (Stream<Path> stream = Files.walk(jspRoot)) {
            stream.filter(Files::isRegularFile)
                    .filter(this::isUsageFile)
                    .forEach(jspFile -> replaceUsages(jspFile, oldJspTagPrefix, oldJspTagClosing, newJteFile));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    protected String readFile(Path jspTag) {
        return IoUtils.readFile(jspTag);
    }

    private void replaceUsages(Path jspFile, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        String original = IoUtils.readFile(jspFile);
        String replaced = replaceUsages(original, oldJspTagPrefix, oldJspTagClosing, newJteFile);
        if (!original.equals(replaced)) {
            IoUtils.writeFile(jspFile, replaced);
        }
    }

    private String replaceUsages(String content, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        StringBuilder jspContent = new StringBuilder(content);
        int lastIndex = 0;
        while ((lastIndex = jspContent.indexOf(oldJspTagPrefix, lastIndex)) >= 0) {
            int suffixIndex = lastIndex + oldJspTagPrefix.length();
            if (suffixIndex < jspContent.length()) {
                char character = jspContent.charAt(suffixIndex);
                if (Character.isWhitespace(character) || character == '/' || character == '>') {
                    jspContent.replace(lastIndex, suffixIndex, "<" + jteTag + " jte=\"" + newJteFile + "\"");
                    continue;
                }
            }
            lastIndex++;
        }

        lastIndex = 0;
        while ((lastIndex = jspContent.indexOf(oldJspTagClosing, lastIndex)) >= 0) {
            jspContent.replace(lastIndex, lastIndex + oldJspTagClosing.length(), "</" + jteTag + ">");
        }
        return jspContent.toString();
    }

    private String extractTagPrefix(Path jspTag) {
        String fileName = jspTag.getFileName().toString();
        String tagName = fileName.substring(0, fileName.indexOf('.'));
        Path parent = jspTag.getParent();
        String namespace = parent == null ? "tags" : parent.getFileName().toString();
        if ("tags".equals(namespace)) {
            namespace = "include";
        }
        return "<" + namespace + ":" + tagName;
    }

    protected URL getResourceBase() {
        try {
            return Paths.get("").toUri().toURL();
        } catch (MalformedURLException e) {
            throw new UncheckedIOException(e);
        }
    }

    public String suggestJteFile(String jspFile) {
        int fileSeparatorIndex = jspFile.indexOf('.');
        if (fileSeparatorIndex == -1) {
            throw new IllegalArgumentException("JSP file without file extension " + jspFile);
        }
        StringBuilder jteFile = new StringBuilder(jspFile.substring(0, fileSeparatorIndex));
        CamelCaseConverter.convertTo(jteFile);
        jteFile.append(".jte");
        return jteFile.toString();
    }

    protected void checkDependencies(String jteCode) {
        List<String> unresolvedJspTags = findUnresolvedJspTags(jteCode);
        if (unresolvedJspTags.isEmpty()) {
            return;
        }
        Set<String> notConvertedTagsSet = getNotConvertedTagsAsSet();
        Set<String> errors = new LinkedHashSet<>();
        for (String unresolvedJspTag : unresolvedJspTags) {
            if (!notConvertedTagsSet.contains(unresolvedJspTag)) {
                errors.add("The tag " + unresolvedJspTag + "/> is used by this tag and not converted to jte yet. You should convert " + unresolvedJspTag + "/> first. If this is a tag that should be always converted by hand, implement getNotConvertedTags() and add it there.");
            }
        }
        if (!errors.isEmpty()) {
            throw new UnsupportedOperationException(String.join("\n", errors));
        }
    }

    private Set<String> getNotConvertedTagsAsSet() {
        String[] notConvertedTags = getNotConvertedTags();
        Set<String> result = new HashSet<>();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                result.add("<" + notConvertedTag);
            }
        }
        return result;
    }

    protected List<String> findUnresolvedJspTags(String jteCode) {
        List<String> result = new ArrayList<>();
        Matcher matcher = UNCONVERTED_TAG_REFERENCES.matcher(jteCode);
        while (matcher.find()) {
            result.add(matcher.group());
        }
        return result;
    }

    protected String[] getNotConvertedTags() {
        return null;
    }

    private String toPortablePath(Path path) {
        return path.toString().replace('\\', '/');
    }
