package gg.jte.convert.jsp;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.catchThrowable;

class JspMigrationPlanTest {
    @TempDir
    Path tempDir;

    @Test
    void plansAndCommitsDependenciesTransactionally() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/a.tag"), "<my:b/>");
        write(jspRoot.resolve("my/b.tag"), "B");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<my:a/><my:b/>");
        TestConverter converter = new TestConverter(jspRoot, jteRoot);

        JspMigrationPlan plan = converter.planTags(List.of("my/a.tag", "my/b.tag"), null);

        assertThat(plan.getConversionOrder()).containsExactly(jspRoot.resolve("my/b.tag"), jspRoot.resolve("my/a.tag"));
        assertThat(plan.getDeletes()).containsExactlyInAnyOrder(jspRoot.resolve("my/a.tag"), jspRoot.resolve("my/b.tag"));
        assertThat(plan.getWrites()).containsKeys(jteRoot.resolve("my/a.jte"), jteRoot.resolve("my/b.jte"), usage);
        assertThat(plan.getWrites().get(jteRoot.resolve("my/a.jte"))).contains("@template.my.b()", "A").doesNotContain("<my:b");
        assertThat(Files.readString(usage)).isEqualTo("<my:a/><my:b/>");
        assertThat(jteRoot).doesNotExist();
        assertThatThrownBy(() -> plan.getWrites().put(usage, "changed")).isInstanceOf(UnsupportedOperationException.class);

        plan.commit();

        assertThat(jspRoot.resolve("my/a.tag")).doesNotExist();
        assertThat(jspRoot.resolve("my/b.tag")).doesNotExist();
        assertThat(jteRoot.resolve("my/a.jte")).hasContent(plan.getWrites().get(jteRoot.resolve("my/a.jte")));
        assertThat(usage).hasContent(plan.getWrites().get(usage));
        assertThatThrownBy(plan::commit).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void findsDependenciesInApprovedIncludesButNotComments() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/a.tag"), "<%@ include file=\"/WEB-INF/dependency.jsp.inc\" %><%-- <my:c/> --%>A");
        write(jspRoot.resolve("my/b.tag"), "B");
        write(jspRoot.resolve("my/c.tag"), "C");
        write(jspRoot.resolve("WEB-INF/dependency.jsp.inc"), "<my:b/>");
        TestConverter converter = new TestConverter(jspRoot, jteRoot);

        JspMigrationPlan plan = converter.planTags(List.of("my/c.tag", "my/b.tag", "my/a.tag"), c -> c.addInlinedInclude("/WEB-INF/dependency.jsp.inc"));

        assertThat(plan.getConversionOrder()).containsExactly(
                jspRoot.resolve("my/b.tag"),
                jspRoot.resolve("my/a.tag"),
                jspRoot.resolve("my/c.tag")
        );
    }

    @Test
    void rejectsCyclesWithDeterministicClosedPath() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        write(jspRoot.resolve("my/a.tag"), "<my:b/>");
        write(jspRoot.resolve("my/b.tag"), "<my:a/>");
        TestConverter converter = new TestConverter(jspRoot, tempDir.resolve("jte"));

        assertThatThrownBy(() -> converter.planTags(List.of("my/b.tag", "my/a.tag"), null))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage("Cyclic JSP tag dependency: my/a.tag -> my/b.tag -> my/a.tag");
    }

    @Test
    void stalePlanReportsAllChangedPathsWithoutMutation() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path tag = write(jspRoot.resolve("my/a.tag"), "A");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<my:a/>");
        TestConverter converter = new TestConverter(jspRoot, jteRoot);
        JspMigrationPlan plan = converter.planTags(List.of("my/a.tag"), null);
        Files.writeString(tag, "changed", StandardCharsets.UTF_8);
        Files.writeString(usage, "changed usage", StandardCharsets.UTF_8);
        Path destination = jteRoot.resolve("my/a.jte");
        write(destination, "occupied");

        Throwable throwable = catchThrowable(plan::commit);

        assertThat(throwable).isInstanceOf(StaleJspMigrationPlanException.class);
        assertThat(((StaleJspMigrationPlanException) throwable).getChangedPaths()).containsExactly(tag, usage, destination);
        assertThat(tag).hasContent("changed");
        assertThat(usage).hasContent("changed usage");
        assertThat(destination).hasContent("occupied");
    }

    @Test
    void rollsBackWritesAndCreatedDirectoriesAfterIoFailure() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path first = write(jspRoot.resolve("my/a.tag"), "A");
        Path second = write(jspRoot.resolve("my/b.tag"), "B");
        TestConverter converter = new TestConverter(jspRoot, jteRoot) {
            @Override
            public String suggestJteFile(String jspFile) {
                return jspFile.endsWith("a.tag") ? "a.jte" : "blocked/b.jte";
            }
        };
        JspMigrationPlan plan = converter.planTags(List.of("my/a.tag", "my/b.tag"), null);
        Path blockingFile = write(jteRoot.resolve("blocked"), "unrelated");

        assertThatThrownBy(plan::commit).isInstanceOf(IOException.class);

        assertThat(first).hasContent("A");
        assertThat(second).hasContent("B");
        assertThat(jteRoot.resolve("a.jte")).doesNotExist();
        assertThat(blockingFile).hasContent("unrelated");
    }

    @Test
    void parserSetupFailureSurfacesUnchanged() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        write(jspRoot.resolve("my/a.tag"), "A");
        TestConverter converter = new TestConverter(jspRoot, tempDir.resolve("jte"));
        RuntimeException expected = new RuntimeException("setup failed");

        assertThat(catchThrowable(() -> converter.planTags(List.of("my/a.tag"), c -> { throw expected; }))).isSameAs(expected);
    }

    private Path write(Path path, String content) throws IOException {
        Files.createDirectories(path.getParent());
        Files.writeString(path, content, StandardCharsets.UTF_8);
        return path.toAbsolutePath().normalize();
    }

    private static class TestConverter extends JspToJteConverter {
        private final Path jspRoot;

        private TestConverter(Path jspRoot, Path jteRoot) {
            super(jspRoot, jteRoot, "my:jte");
            this.jspRoot = jspRoot;
        }

        @Override
        protected URL getResourceBase() {
            try {
                return jspRoot.toUri().toURL();
            } catch (MalformedURLException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public String suggestJteFile(String jspFile) {
            return super.suggestJteFile(jspFile);
        }
    }
}
