        return content.replace("\r", "").getBytes(StandardCharsets.UTF_8);
    }

    private String replaceJspTagWithJteCall(String content, Path jspTag, Path jteTagPath) {
        String opening = extractTagPrefix(jspTag);
        String closing = "</" + opening.substring(1) + ">";
        String template = toPortablePath(jteRoot.relativize(jteTagPath));
        template = template.substring(0, template.length() - 4).replace('/', '.');
        StringBuilder result = new StringBuilder(content);
        int searchFrom = 0;
        while (true) {
            int start = result.indexOf(opening, searchFrom);
            if (start < 0) {
                break;
            }
            if (isInsideJspComment(result, start)) {
                searchFrom = start + opening.length();
                continue;
            }
            int suffix = start + opening.length();
            if (suffix >= result.length()) {
                break;
            }
            char boundary = result.charAt(suffix);
            if (!Character.isWhitespace(boundary) && boundary != '/' && boundary != '>') {
                searchFrom = suffix;
                continue;
            }
            int openingEnd = findTagEnd(result, suffix);
            if (openingEnd < 0) {
                break;
            }
            boolean selfClosing = result.charAt(openingEnd - 1) == '/';
            int end = openingEnd + 1;
            String body = null;
            if (!selfClosing) {
                int closingStart = result.indexOf(closing, end);
                if (closingStart >= 0) {
                    body = result.substring(end, closingStart);
                    end = closingStart + closing.length();
                }
            }
            String attributes = result.substring(suffix, selfClosing ? openingEnd - 1 : openingEnd);
            String replacement = createJteCall(template, attributes, body);
            result.replace(start, end, replacement);
            searchFrom = start + replacement.length();
        }
        return result.toString();
    }

    private int findTagEnd(CharSequence content, int from) {
        char quote = 0;
        for (int i = from; i < content.length(); i++) {
            char current = content.charAt(i);
            if (quote == 0 && (current == '\'' || current == '"')) {
                quote = current;
            } else if (quote == current) {
                quote = 0;
            } else if (quote == 0 && current == '>') {
                return i;
            }
        }
        return -1;
    }

    private boolean isInsideJspComment(CharSequence content, int index) {
        String prefix = content.subSequence(0, index).toString();
        return prefix.lastIndexOf("<%--") > prefix.lastIndexOf("--%>");
    }

    private String createJteCall(String template, String attributes, String body) {
        List<String> parameters = new ArrayList<>();
        Matcher matcher = Pattern.compile("([a-zA-Z_][a-zA-Z0-9_:-]*)\\s*=\\s*([\"'])(.*?)\\2", Pattern.DOTALL).matcher(attributes);
        while (matcher.find()) {
            parameters.add(matcher.group(1) + " = " + JspExpressionConverter.convertAttributeValue(matcher.group(3)));
        }
        if (body != null && !body.isEmpty()) {
            parameters.add("bodyContent = @`" + body + "`");
        }
        return "@template." + template + "(" + String.join(", ", parameters) + ")";
    }

    private void replaceVirtualUsages(Map<Path, String> contents, Path jspTag, Path jteTagPath) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = toPortablePath(jteRoot.relativize(jteTagPath));
        for (Map.Entry<Path, String> entry : contents.entrySet()) {
            entry.setValue(replaceUsages(entry.getValue(), oldJspTagPrefix, oldJspTagClosing, newJteFile));
        }
    }

